(function(root){const remote=location.hostname.endsWith('github.io')?'https://quant-game.angela-tech.com':'';let token='',session='',available=false,voice=false,seq=0,controller=null,audio=null;const headers=key=>({'content-type':'application/json','x-csrf-token':token,'x-session-token':session,'idempotency-key':key});const A={enabled:false,async status(){if(location.protocol==='file:')return {mode:'mock',voice:'mock'};try{const r=await fetch(remote+'/api/status',{credentials:remote?'omit':'same-origin'});const d=await r.json();token=d.csrf||'';session=d.session||'';available=d.mode==='available';voice=d.voice==='available';return d}catch{return {mode:'mock',voice:'mock'}}},cancel(){seq++;controller?.abort();controller=null;audio?.pause?.();audio=null;},async request(kind,data,key){if(!A.enabled||!available)return null;A.cancel();const generation=seq;controller=new AbortController();try{const r=await fetch(remote+'/api/'+kind,{method:'POST',credentials:remote?'omit':'same-origin',headers:headers(key),body:JSON.stringify({...data,consent:true}),signal:controller.signal});if(!r.ok)return null;const d=await r.json();return generation===seq&&d.mode==='ai'?d.result:null}catch{return null}finally{if(generation===seq)controller=null}},async speak(role,text){if(!A.enabled||!voice||!text)return false;try{const r=await fetch(remote+'/api/voice',{method:'POST',credentials:remote?'omit':'same-origin',headers:headers('voice-'+Date.now()),body:JSON.stringify({role,text,consent:true})});if(!r.ok||!r.headers.get('content-type')?.startsWith('audio/'))return false;const url=URL.createObjectURL(await r.blob());audio=new Audio(url);audio.onended=()=>URL.revokeObjectURL(url);await audio.play();return true}catch{return false}},get available(){return available}};root.PandaAI=A;})(window);
